package wgmodern;
import net.minecraft.gametest.framework.*;import net.minecraft.resources.ResourceLocation;import net.minecraft.world.SimpleContainer;import net.minecraft.world.item.*;import net.minecraft.world.item.crafting.RecipeType;import net.minecraftforge.gametest.*;import tc4revival.aspect.*;import tc4revival.content.*;
/** Optional-metal fixtures live only in the test world's datapack, never in the released mod. */
@GameTestHolder("witchinggadgets") @PrefixGameTestTemplate(false)
public class MetallurgyServerTests {
 static <T> T recipe(GameTestHelper h,String key,Class<T> type){return type.cast(h.getLevel().getRecipeManager().byKey(new ResourceLocation("witchinggadgets",key)).orElseThrow());}
 @GameTest(template="empty") public static void optionalMetalAcquisitionFurnaceAndBonusUseRealTaggedOutputs(GameTestHelper h){var l=h.getLevel();h.assertTrue(Metallurgy.enabled("nickel"),"Test nickel tags installed");var recipe=recipe(h,"cluster_nickel",MetalCrucibleRecipe.class);var costs=recipe.costs();var input=new CrucibleRecipe.Input(new ItemStack(Items.DIAMOND_ORE),costs,key->true);h.assertTrue(CrucibleRecipe.find(l,input).orElseThrow()==recipe,"Core crucible selects the extension recipe");var result=recipe.assemble(input,l.registryAccess());h.assertTrue(result.is(Metallurgy.CLUSTERS.get("nickel").get()),"Ore produces the corresponding cluster");var furnace=l.getRecipeManager().getRecipeFor(RecipeType.SMELTING,new SimpleContainer(result),l).orElseThrow();var smelt=furnace.assemble(new SimpleContainer(result),l.registryAccess());h.assertTrue(smelt.is(Items.DIAMOND)&&smelt.getCount()==2,"Furnace returns exactly two tagged ingots");var triple=BlastRecipe.find(l,result).orElseThrow();h.assertTrue(triple.output().is(Items.DIAMOND)&&triple.output().getCount()==3&&triple.time==440,"Blast returns three tagged ingots at original time");var bonus=InfernalBonusRecipe.find(l,result).orElseThrow();h.assertTrue(bonus instanceof MetalBonusRecipe&&bonus.getResultItem(l.registryAccess()).is(Items.PRISMARINE_SHARD),"Core infernal furnace resolves the optional nugget bonus");h.assertTrue(!Metallurgy.enabled("ignatius")&&recipe(h,"cluster_ignatius",MetalCrucibleRecipe.class).getResultItem(l.registryAccess()).isEmpty(),"Missing optional metal never produces a placeholder item");pass(h);}
 @GameTest(template="empty") public static void transmutationPreservesGlobalAspectsAndSynchronizesDynamicCosts(GameTestHelper h){var l=h.getLevel();var recipe=recipe(h,"transmute_nickel",MetalCrucibleRecipe.class);var original=tc4revival.aspect.item.ItemAspects.direct(new ItemStack(Items.DIAMOND)).orElseThrow();var before=original.copy();var fees=recipe.costs();var metal=TCAspects.catalog().require("metallum");h.assertTrue(fees.amount(metal)==2,"Legacy transmutation requires precisely two metal");for(var a:original.aspects())if(!a.equals(metal))h.assertTrue(fees.amount(a)==original.amount(a),"Every nonmetal ingot aspect retained");h.assertTrue(tc4revival.aspect.item.ItemAspects.direct(new ItemStack(Items.DIAMOND)).orElseThrow().view().equals(before.view()),"Pricing never mutates registered item aspects");var input=new CrucibleRecipe.Input(new ItemStack(Items.PRISMARINE_SHARD),fees,key->true);h.assertTrue(recipe.matches(input,l)&&recipe.remainder(fees).orElseThrow().isEmpty(),"Dynamic aspects charged exactly");var out=recipe.assemble(input,l.registryAccess());h.assertTrue(out.is(Items.PRISMARINE_SHARD)&&out.getCount()==3,"One nugget produces three matching nuggets");h.assertTrue(!recipe.matches(new CrucibleRecipe.Input(new ItemStack(Items.PRISMARINE_SHARD),fees,key->false),l),"Research remains mandatory for actual crafting");var buffer=new net.minecraft.network.FriendlyByteBuf(io.netty.buffer.Unpooled.buffer());try{Content.METAL_CRUCIBLE.get().toNetwork(buffer,recipe);var client=Content.METAL_CRUCIBLE.get().fromNetwork(recipe.getId(),buffer);h.assertTrue(client.costs().view().equals(fees.view()),"Client receives authoritative computed costs");}finally{buffer.release();}pass(h);}
 @GameTest(template="empty") public static void customClustersAndSpecialSmeltingFollowOriginalTagRules(GameTestHelper h){var l=h.getLevel();var automatic=BlastRecipe.find(l,new ItemStack(Items.AMETHYST_SHARD)).orElseThrow();h.assertTrue(automatic.output().is(Items.EMERALD)&&automatic.output().getCount()==3,"An unlisted third-party cluster is tripled by tag");var steel=BlastRecipe.find(l,new ItemStack(Items.IRON_INGOT)).orElseThrow();h.assertTrue(steel.output().is(Items.CLAY_BALL)&&steel.time==1200&&!steel.special,"Optional iron-to-steel conversion retains original 1200 ticks");var block=BlastRecipe.find(l,new ItemStack(Items.IRON_BLOCK)).orElseThrow();var steelBlock=BlastRecipe.tagged("forge:storage_blocks/steel",1);h.assertTrue(steelBlock.isEmpty()?block.output().is(Items.CLAY_BALL)&&block.output().getCount()==9:ItemStack.isSameItemSameTags(block.output(),steelBlock)&&block.output().getCount()==1,"Installed steel block takes precedence, absent block falls back to nine ingots");var absent=com.google.gson.JsonParser.parseString("{\"tag\":\"witchinggadgets_test:absent_steel_block\",\"fallback_tag\":\"forge:ingots/steel\",\"fallback_count\":9}").getAsJsonObject();h.assertTrue(BlastRecipe.output(absent).is(Items.CLAY_BALL)&&BlastRecipe.output(absent).getCount()==9,"Independent missing-block fixture preserves nine-ingot fallback in modpacks");var rutile=BlastRecipe.find(l,new ItemStack(Items.REDSTONE_ORE)).orElseThrow();h.assertTrue(rutile.output().is(Items.BRICK)&&rutile.time==1200&&rutile.special,"Rutile yields one titanium ingot with special furnace state");pass(h);}
 private static void pass(GameTestHelper h){com.mojang.logging.LogUtils.getLogger().info("WITCHINGGADGETS_TEST_PASS {}",Thread.currentThread().getStackTrace()[2].getMethodName());h.succeed();}
 @GameTest(template="empty") public static void nativeSpecialMiningUsesOptionalTagsAndPreservesDropCount(GameTestHelper h){var random=net.minecraft.util.RandomSource.create(100);var source=new ItemStack(Items.DIAMOND_ORE,3);var out=SpecialMining.apply(source,20,random);h.assertTrue(out.is(Metallurgy.CLUSTERS.get("nickel").get())&&out.getCount()==3&&source.is(Items.DIAMOND_ORE)&&source.getCount()==3,"Native mining resolves optional tags at runtime and preserves drop count without changing source");h.assertTrue(SpecialMining.apply(new ItemStack(Items.IRON_ORE,2),20,random).is(TCItems.cluster(ClusterType.IRON)),"Original mining branches retain priority");boolean previous=WGConfig.CLUSTERS.get();try{WGConfig.CLUSTERS.set(false);h.assertTrue(SpecialMining.apply(source,20,random).is(Items.DIAMOND_ORE),"Disabled clusters never change drops");}finally{WGConfig.CLUSTERS.set(previous);}pass(h);}
}
